let workoutStarted=0,restTimer=null,restExpired=false,workoutAudio=null;
window.isWorkoutActive=()=>!!workoutStarted;
const restDock=document.createElement('section');restDock.id='rest-dock';restDock.hidden=true;document.body.append(restDock);
function clockText(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function prepareWorkoutAudio(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(Audio){workoutAudio??=new Audio();workoutAudio.resume().catch(()=>{})}}catch{}}
function restSound(){try{if(workoutAudio?.state==='running'){for(let i=0;i<3;i++){const oscillator=workoutAudio.createOscillator(),gain=workoutAudio.createGain(),at=workoutAudio.currentTime+i*.35;oscillator.frequency.value=880;gain.gain.setValueAtTime(.12,at);gain.gain.exponentialRampToValueAtTime(.001,at+.2);oscillator.connect(gain);gain.connect(workoutAudio.destination);oscillator.start(at);oscillator.stop(at+.22)}}}catch{}try{navigator.vibrate?.([180,90,180])}catch{}}
window.startWorkout=()=>{if(role!=='aluno'||workoutStarted)return;if(!plan().length){toast('Seu personal ainda precisa adicionar os exercícios.');return}workoutStarted=Date.now();done.clear();prepareWorkoutAudio();render();toast('Treino iniciado. Bom treino!')};
window.startRest=index=>{if(role!=='aluno'||!workoutStarted){toast('Inicie seu treino primeiro.');return}if(restTimer){toast('Finalize o descanso atual antes de começar outro.');return}const x=plan()[index];if(!x)return;const seconds=Math.max(0,Number(x.rest)||0);if(!seconds){toast('Este exercício não tem intervalo de descanso.');return}prepareWorkoutAudio();restExpired=false;restTimer={name:x.name,end:Date.now()+seconds*1000};restDock.hidden=false;restDock.innerHTML=`<span class="eyebrow">DESCANSO · ${esc(x.name)}</span><div class="row"><strong id="rest-clock" role="timer" aria-label="Tempo restante de descanso">${clockText(seconds)}</strong><button onclick="endRest()">Voltar ao exercício</button></div><p id="rest-message" role="alert">Recupere o fôlego. Avisaremos quando o intervalo terminar.</p>`;tickWorkout()};
window.endRest=()=>{restTimer=null;restExpired=false;restDock.hidden=true;restDock.classList.remove('expired')};
function tickWorkout(){const duration=$('#workout-duration');if(duration&&workoutStarted)duration.textContent=clockText(Math.max(0,Math.floor((Date.now()-workoutStarted)/1000)));if(!restTimer)return;const seconds=Math.max(0,Math.ceil((restTimer.end-Date.now())/1000));$('#rest-clock').textContent=clockText(seconds);if(seconds===0&&!restExpired){restExpired=true;restDock.classList.add('expired');$('#rest-message').textContent='Tempo de descanso encerrado! Volte ao exercício para não ultrapassar o intervalo.';restSound()}}
setInterval(tickWorkout,250);document.addEventListener('visibilitychange',tickWorkout);
const workoutRender=render;render=function(){workoutRender();if(role==='aluno'&&page==='treinos'){const card=document.createElement('section');card.className='card workout-controls';card.innerHTML=`<div class="row"><div><span class="eyebrow">${workoutStarted?'TREINO EM ANDAMENTO':'PRONTO PARA COMEÇAR?'}</span><h2>${workoutStarted?'Foco em cada série.':'Seu treino começa aqui.'}</h2><p>${workoutStarted?'Ao concluir um exercício, o descanso começa automaticamente. Você também pode usar “Descansar” entre as séries.':'Toque em Iniciar treino para ativar os exercícios e o cronômetro de descanso.'}</p></div>${workoutStarted?`<strong id="workout-duration" aria-label="Duração do treino">${clockText(Math.floor((Date.now()-workoutStarted)/1000))}</strong>`:'<button class="primary" onclick="startWorkout()">▶ Iniciar treino</button>'}</div><p class="note">Mantenha o app aberto para receber o alerta. Som e vibração dependem do navegador e das configurações do aparelho.</p>`;$('#content').children[0].after(card);tickWorkout()}};
const exerciseToggle=window.toggle;window.toggle=index=>{if(!workoutStarted){toast('Toque em Iniciar treino antes de concluir os exercícios.');return}const completing=!done.has(index);if(completing&&restTimer){toast('Encerre o descanso atual antes de concluir outro exercício.');return}exerciseToggle(index);if(completing)window.startRest(index)};
const finishWorkout=window.finish;window.finish=()=>{if(!workoutStarted){toast('Inicie seu treino primeiro.');return}if(restTimer){toast('Toque em Voltar ao exercício para encerrar o descanso.');return}if(done.size!==plan().length||!plan().length){toast('Conclua todos os exercícios antes de finalizar.');return}finishWorkout();const form=$('#finishForm');if(!form)return;const submit=form.onsubmit;form.onsubmit=event=>{const count=data.logs.length;submit(event);if(data.logs.length>count){data.logs.at(-1).durationSeconds=Math.floor((Date.now()-workoutStarted)/1000);save();workoutStarted=0;window.endRest();render()}}};
const workoutLogout=logoutButton.onclick;logoutButton.onclick=()=>{workoutStarted=0;window.endRest();workoutLogout()};


